<?php if (!defined('ABSPATH')) { exit; } get_header();
function modsite_get_filter($key) { return isset($_GET[$key])&&is_string($_GET[$key]) ? sanitize_text_field(wp_unslash($_GET[$key])) : ''; }
$search=modsite_get_filter('mod_q');$game=sanitize_title(modsite_get_filter('mod_game'));$category=sanitize_title(modsite_get_filter('mod_category'));$sort=modsite_get_filter('mod_sort');$page=max(1,absint($_GET['mod_page']??1));
$args=['post_type'=>'modsite_mod','post_status'=>'publish','posts_per_page'=>12,'paged'=>$page,'s'=>$search,'orderby'=>$sort==='az'?'title':($sort==='updated'?'modified':'date'),'order'=>$sort==='az'?'ASC':'DESC'];
$tax=[];if ($game) { $tax[]=['taxonomy'=>'modsite_game','field'=>'slug','terms'=>$game]; }if ($category) { $tax[]=['taxonomy'=>'modsite_category','field'=>'slug','terms'=>$category]; }if ($tax) { $args['tax_query']=array_merge(['relation'=>'AND'],$tax); }
$mods=new WP_Query($args); ?>
<main id="main"><div class="intro-label"><span class="live-dot"></span>TWOJA GRA. WIĘCEJ MOŻLIWOŚCI.</div><div class="intro-row"><h1>Zmień zasady <em>gry.</em></h1><span class="catalog-tag">KATALOG MODYFIKACJI</span></div><p class="intro-copy">Odkrywaj nowe możliwości swoich ulubionych gier. Wybierz modyfikację. Odmień swoją rozgrywkę.</p>
<?php if (!$search&&!$game&&!$category&&$page===1) { $featured=new WP_Query(['post_type'=>'modsite_mod','post_status'=>'publish','posts_per_page'=>1,'no_found_rows'=>true]);if ($featured->have_posts()) { $featured->the_post(); ?>
<section class="featured" aria-label="Wyróżniona modyfikacja"><?php if (has_post_thumbnail()) { the_post_thumbnail('large',['class'=>'featured-bg','fetchpriority'=>'high']); } ?><div class="featured-shade"></div><span class="featured-label">NAJNOWSZA MODYFIKACJA</span><div class="featured-content"><span class="game-eyebrow"><?php echo esc_html(modsite_terms_text(get_the_ID(),'modsite_game')); ?></span><h2><?php echo esc_html(wp_trim_words(get_the_title(),7)); ?></h2><p><?php echo esc_html(wp_trim_words(wp_strip_all_tags(get_the_excerpt()),14)); ?></p><a class="button gold" href="<?php the_permalink(); ?>">Odkryj modyfikację →</a></div></section>
<?php }wp_reset_postdata(); } ?>
<section class="catalog-section" id="catalog"><div class="section-head"><h2>Odkrywaj modyfikacje<span><?php echo absint($mods->found_posts); ?></span></h2><?php if ($search||$game||$category) { ?><a class="text-button" href="<?php echo esc_url(home_url('/')); ?>">Wyczyść filtry ×</a><?php } ?></div>
<form class="catalog-toolbar" method="get" action="<?php echo esc_url(home_url('/')); ?>"><label class="search"><span aria-hidden="true">⌕</span><input type="search" name="mod_q" value="<?php echo esc_attr($search); ?>" placeholder="Szukaj modyfikacji, gry…" aria-label="Szukaj modyfikacji"></label><label class="sort-label"><span class="sr-only">Sortowanie</span><select name="mod_sort"><option value="newest" <?php selected($sort,'newest'); ?>>Najnowsze</option><option value="az" <?php selected($sort,'az'); ?>>Nazwa: A–Z</option><option value="updated" <?php selected($sort,'updated'); ?>>Ostatnio zaktualizowane</option></select></label><?php if ($game) { ?><input type="hidden" name="mod_game" value="<?php echo esc_attr($game); ?>"><?php } ?><?php if ($category) { ?><input type="hidden" name="mod_category" value="<?php echo esc_attr($category); ?>"><?php } ?><button class="button gold" type="submit">Szukaj</button></form>
<div class="filter-chips"><a class="chip <?php echo !$game?'selected':''; ?>" href="<?php echo esc_url(home_url('/')); ?>">Wszystkie</a><?php $games=get_terms(['taxonomy'=>'modsite_game','hide_empty'=>true]);if (!is_wp_error($games)) { foreach ($games as $term) { echo '<a class="chip '.($game===$term->slug?'selected':'').'" href="'.esc_url(modsite_catalog_url(['mod_game'=>$term->slug])).'">'.esc_html($term->name).'</a>'; } } ?></div>
<div class="mod-list"><?php if ($mods->have_posts()) { while ($mods->have_posts()) { $mods->the_post();modsite_render_mod_card(); } } else { ?><div class="empty-state"><h3>Tu pojawią się modyfikacje.</h3><p><?php echo $search||$game||$category ? 'Nie znaleziono wpisów. Zmień filtry.' : 'Katalog czeka na pierwsze publikacje.'; ?></p><?php if (current_user_can('edit_posts')) { ?><a class="button gold" href="<?php echo esc_url(admin_url('post-new.php?post_type=modsite_mod')); ?>">Dodaj modyfikację</a><?php } ?></div><?php }wp_reset_postdata(); ?></div>
<?php if ($mods->max_num_pages>1) { echo '<nav class="pagination" aria-label="Kolejne strony">'.wp_kses_post(paginate_links(['base'=>add_query_arg('mod_page','%#%'),'format'=>'','current'=>$page,'total'=>$mods->max_num_pages,'prev_text'=>'← Poprzednia','next_text'=>'Następna →'])).'</nav>'; } ?>
</section></main><?php get_footer(); ?>
